"""matplotlib.ticker — tick locating and formatting."""

import sys as _sys
import numpy as _np


# Shared no-op fallback for unknown Locator/Formatter methods.
_ticker_warned = set()

def _ticker_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _ticker_warned:
        _ticker_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] ticker.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Locator:
    """Base tick locator."""
    MAXTICKS = 1000
    __getattr__ = _ticker_getattr_fallback

    def __call__(self):
        return self.tick_values(None, None)

    def tick_values(self, vmin, vmax):
        return []

    def set_params(self, **kwargs):
        for k, v in kwargs.items():
            setattr(self, k, v)

    def view_limits(self, vmin, vmax):
        return (vmin, vmax)

    def autoscale(self):
        return self.view_limits(None, None)

    def pan(self, numsteps): pass
    def zoom(self, direction): pass
    def refresh(self): pass
    def raise_if_exceeds(self, locs): return locs
    def nonsingular(self, v0, v1):
        if v0 == v1:
            return (v0 - 1, v1 + 1)
        return (v0, v1)
    def create_dummy_axis(self, **kw):
        self.axis = type('_DA', (), {'get_view_interval': lambda s: (0, 1),
                                      'get_data_interval': lambda s: (0, 1)})()
    def set_axis(self, axis):
        self.axis = axis


def _nice_step(raw_step, steps):
    """Pick the smallest "nice" step from ``steps`` that is ≥ ``raw_step``
    after rescaling. Mirrors upstream's algorithm in MaxNLocator.

    ``steps`` is something like ``(1, 2, 2.5, 5, 10)`` — the canonical
    matplotlib "round numbers". We pull ``raw_step`` into the [1, 10)
    range, pick the first nice step that covers it, then scale back.
    """
    if raw_step <= 0:
        return 1.0
    mag = 10 ** _np.floor(_np.log10(raw_step))
    normalized = raw_step / mag
    for s in steps:
        if s >= normalized:
            return float(s * mag)
    return float(steps[-1] * mag * 10)


class MaxNLocator(Locator):
    """Find ≤ ``nbins`` tick positions at "nice" round-number multiples
    inside [vmin, vmax]. The algorithm mirrors upstream:

      1. raw_step = (vmax - vmin) / nbins
      2. round raw_step up to the next nice step from ``steps``
      3. emit ticks at integer multiples of that step.
    """

    default_params = dict(nbins=10, steps=(1, 2, 2.5, 5, 10), integer=False,
                          symmetric=False, prune=None, min_n_ticks=2)

    def __init__(self, nbins='auto', *, steps=None, integer=False,
                 symmetric=False, prune=None, min_n_ticks=2):
        self._nbins = nbins  # may be 'auto'
        self.steps = tuple(steps) if steps else (1, 2, 2.5, 5, 10)
        self.integer = bool(integer)
        self.symmetric = bool(symmetric)
        self.prune = prune
        self.min_n_ticks = int(min_n_ticks)

    @property
    def nbins(self):
        return 9 if self._nbins == 'auto' else int(self._nbins)

    @nbins.setter
    def nbins(self, v):
        self._nbins = v

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            return []
        vmin, vmax = sorted((float(vmin), float(vmax)))
        if vmin == vmax:
            vmin, vmax = self.nonsingular(vmin, vmax)
        n = self.nbins
        raw = (vmax - vmin) / max(n, 1)
        step = _nice_step(raw, self.steps)
        if self.integer:
            step = max(1.0, _np.round(step))
        # Snap vmin down, vmax up to multiples of the step.
        lo = _np.floor(vmin / step) * step
        hi = _np.ceil(vmax / step) * step
        ticks = _np.arange(lo, hi + step * 0.5, step)
        # Filter to inside [vmin, vmax] with a small margin.
        margin = step * 1e-9
        ticks = ticks[(ticks >= vmin - margin) & (ticks <= vmax + margin)]
        if self.prune == 'lower' and len(ticks) > 1:
            ticks = ticks[1:]
        elif self.prune == 'upper' and len(ticks) > 1:
            ticks = ticks[:-1]
        elif self.prune == 'both' and len(ticks) > 2:
            ticks = ticks[1:-1]
        return ticks.tolist()


class MultipleLocator(Locator):
    """Ticks at integer multiples of ``base`` (with optional ``offset``)."""

    def __init__(self, base=1.0, offset=0.0):
        self.base = float(base)
        self.offset = float(offset)

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            return []
        lo = _np.ceil((vmin - self.offset) / self.base) * self.base + self.offset
        hi = _np.floor((vmax - self.offset) / self.base) * self.base + self.offset
        return _np.arange(lo, hi + self.base * 0.5, self.base).tolist()


class FixedLocator(Locator):
    """User-supplied fixed list of tick positions."""

    def __init__(self, locs, nbins=None):
        self.locs = list(locs)
        self.nbins = nbins

    def tick_values(self, vmin, vmax):
        if self.nbins is None:
            return list(self.locs)
        # Sub-sample down to nbins ticks.
        step = max(1, int(round(len(self.locs) / self.nbins)))
        return list(self.locs[::step])


class IndexLocator(Locator):
    """Ticks at ``base*i + offset`` covering the data interval."""

    def __init__(self, base, offset):
        self.base = float(base)
        self.offset = float(offset)

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            if self.axis is not None:
                dmin, dmax = self.axis.get_data_interval()
            else:
                return []
        else:
            dmin, dmax = float(vmin), float(vmax)
        lo = _np.ceil((dmin - self.offset) / self.base) * self.base + self.offset
        hi = _np.floor((dmax - self.offset) / self.base) * self.base + self.offset
        return _np.arange(lo, hi + self.base * 0.5, self.base).tolist()


class LinearLocator(Locator):
    """``numticks`` evenly-spaced ticks between vmin and vmax (inclusive)."""

    def __init__(self, numticks=None, presets=None):
        self.numticks = int(numticks) if numticks else 11
        self.presets = presets or {}

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            return []
        return _np.linspace(float(vmin), float(vmax), self.numticks).tolist()


class LogLocator(Locator):
    """Log-scale tick locator. Major ticks at powers of ``base``; minor
    ticks at ``subs * base**k`` (e.g. (2, 3, …, 9) for base 10).
    """

    def __init__(self, base=10.0, subs=(1.0,), numdecs=4, numticks=None):
        self.base = float(base)
        self._subs = subs
        self.numdecs = int(numdecs)
        self.numticks = numticks

    @property
    def subs(self):
        return self._subs

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None or vmax <= 0:
            return []
        b = self.base
        # vmin ≤ 0 is invalid on a log axis — fall back to a decade below
        # vmax so we still produce something usable (mirrors upstream).
        if vmin <= 0:
            vmin = vmax / (b ** self.numdecs)
        log_lo = _np.floor(_np.log(vmin) / _np.log(b))
        log_hi = _np.ceil(_np.log(vmax) / _np.log(b))
        decades = _np.arange(log_lo, log_hi + 1)
        if self._subs is None:
            subs = _np.arange(2.0, b)
        else:
            subs = _np.asarray(self._subs, dtype=float)
        ticks = []
        for d in decades:
            for s in subs:
                t = s * b ** d
                if vmin <= t <= vmax:
                    ticks.append(float(t))
        return sorted(set(ticks))


class SymmetricalLogLocator(Locator):
    """Symmetric-log tick locator — log decades outside [-linthresh, +linthresh]
    plus a linear region inside that interval."""

    def __init__(self, transform=None, subs=None, linthresh=None, base=None):
        self.transform = transform
        self._subs = subs if subs is not None else [1.0]
        if linthresh is not None:
            self.linthresh = float(linthresh)
        elif transform is not None:
            self.linthresh = float(getattr(transform, 'linthresh', 1.0))
        else:
            self.linthresh = 1.0
        if base is not None:
            self.base = float(base)
        elif transform is not None:
            self.base = float(getattr(transform, 'base', 10.0))
        else:
            self.base = 10.0

    @property
    def subs(self):
        return self._subs

    def tick_values(self, vmin, vmax):
        if vmin is None or vmax is None:
            return []
        b = self.base
        lt = self.linthresh
        ticks = set([-lt, 0.0, lt])
        # Positive log decades.
        if vmax > lt:
            log_hi = _np.ceil(_np.log(max(vmax, lt)) / _np.log(b))
            for d in _np.arange(_np.log(lt) / _np.log(b), log_hi + 1):
                for s in self._subs:
                    t = s * b ** d
                    if lt <= t <= vmax:
                        ticks.add(float(t))
        # Negative log decades (mirror).
        if vmin < -lt:
            log_hi = _np.ceil(_np.log(max(-vmin, lt)) / _np.log(b))
            for d in _np.arange(_np.log(lt) / _np.log(b), log_hi + 1):
                for s in self._subs:
                    t = -s * b ** d
                    if vmin <= t <= -lt:
                        ticks.add(float(t))
        return sorted(t for t in ticks if vmin <= t <= vmax)


class AutoLocator(MaxNLocator):
    """MaxNLocator preset with the upstream's default steps and ``nbins='auto'``."""

    def __init__(self):
        super().__init__(nbins='auto', steps=[1, 2, 2.5, 5, 10])


class AutoMinorLocator(Locator):
    """Place minor ticks evenly between consecutive major ticks. ``n``
    is the number of subdivisions per major interval (default chooses
    based on the major step)."""

    def __init__(self, n=None):
        self.ndivs = n

    def tick_values(self, vmin, vmax):
        if self.axis is None:
            return []
        try:
            majors = list(self.axis.get_majorticklocs())
        except Exception:
            return []
        if len(majors) < 2:
            return []
        step = majors[1] - majors[0]
        # If n is not given, pick 4 for "nice" intervals, 5 otherwise.
        ndivs = self.ndivs
        if ndivs is None:
            # If major step is a multiple of 5, use 5 minor divs;
            # if multiple of 2, use 4 minor divs.
            mag = 10 ** _np.floor(_np.log10(abs(step)))
            mantissa = abs(step) / mag
            if abs(mantissa - 5) < 0.01 or abs(mantissa - 2.5) < 0.01:
                ndivs = 5
            else:
                ndivs = 4
        substep = step / ndivs
        minors = []
        for m in majors[:-1]:
            for i in range(1, ndivs):
                minors.append(m + i * substep)
        # Also extend below first major and above last major if inside range.
        first = majors[0]
        i = 1
        while first - i * substep >= vmin:
            minors.append(first - i * substep)
            i += 1
        last = majors[-1]
        i = 1
        while last + i * substep <= vmax:
            minors.append(last + i * substep)
            i += 1
        return sorted(t for t in minors if vmin <= t <= vmax)


class NullLocator(Locator):
    def tick_values(self, vmin, vmax):
        return []


# ── Formatters ──────────────────────────────────────────────────

class Formatter:
    """Base tick formatter."""
    locs = []
    __getattr__ = _ticker_getattr_fallback

    def __call__(self, x, pos=None):
        return self.format_data(x)

    def format_data(self, value):
        return str(value)

    def format_data_short(self, value):
        return self.format_data(value)

    def set_locs(self, locs):
        self.locs = list(locs) if locs is not None else []

    def fix_minus(self, s):
        return s

    def get_offset(self):
        return ''

    def set_offset_string(self, s): pass

    def format_ticks(self, values):
        self.set_locs(values)
        return [self(v, i) for i, v in enumerate(values)]

    def create_dummy_axis(self, **kw):
        self.axis = type('_DA', (), {'get_view_interval': lambda s: (0, 1),
                                      'get_data_interval': lambda s: (0, 1)})()
    def set_axis(self, axis):
        self.axis = axis

    def set_bounds(self, vmin, vmax): pass
    def set_data_interval(self, vmin, vmax): pass
    def set_view_interval(self, vmin, vmax): pass


class FuncFormatter(Formatter):
    def __init__(self, func):
        self.func = func

    def __call__(self, x, pos=None):
        return self.func(x, pos)


class FormatStrFormatter(Formatter):
    def __init__(self, fmt):
        self.fmt = fmt

    def __call__(self, x, pos=None):
        return self.fmt % x


class StrMethodFormatter(Formatter):
    def __init__(self, fmt):
        self.fmt = fmt

    def __call__(self, x, pos=None):
        return self.fmt.format(x=x, pos=pos)


class ScalarFormatter(Formatter):
    """Format tick values as plain decimal strings, switching to
    scientific notation outside ``power_limits`` and optionally
    subtracting a shared offset when values cluster near a midpoint."""

    def __init__(self, useOffset=None, useMathText=None, useLocale=None):
        self._useOffset = True if useOffset is None else useOffset
        self._useMathText = bool(useMathText)
        self._useLocale = bool(useLocale)
        self.orderOfMagnitude = 0
        self.format = ''
        self.offset = 0.0
        self._scientific = True
        self._powerlimits = (-5, 6)

    def __call__(self, x, pos=None):
        if self.orderOfMagnitude == 0 and self.offset == 0:
            return self._format_value(x)
        # Strip the shared offset and order-of-magnitude before formatting.
        v = (x - self.offset) / (10 ** self.orderOfMagnitude)
        return self._format_value(v)

    def _format_value(self, v):
        if v == 0:
            return '0'
        absv = abs(v)
        if self._scientific and (absv != 0 and
                                  (absv < 10 ** self._powerlimits[0]
                                   or absv >= 10 ** self._powerlimits[1])):
            # Scientific notation.
            exp = int(_np.floor(_np.log10(absv)))
            mantissa = v / (10 ** exp)
            if self._useMathText:
                return f'${mantissa:g}\\times 10^{{{exp}}}$'
            return f'{mantissa:g}e{exp:+d}'
        # Plain decimal.
        return f'{v:g}'

    def set_scientific(self, b):
        self._scientific = bool(b)

    def set_powerlimits(self, lims):
        self._powerlimits = tuple(lims)

    def set_useOffset(self, val):
        self._useOffset = val

    def set_locs(self, locs):
        self.locs = list(locs) if locs is not None else []
        if not self.locs:
            self.orderOfMagnitude = 0
            self.offset = 0.0
            return
        # Pick a shared order-of-magnitude if data is far from [0.0001, 1000).
        if self._scientific:
            vmin, vmax = min(self.locs), max(self.locs)
            absmax = max(abs(vmin), abs(vmax))
            if absmax == 0:
                self.orderOfMagnitude = 0
            else:
                exp = int(_np.floor(_np.log10(absmax)))
                if exp < self._powerlimits[0] or exp >= self._powerlimits[1]:
                    self.orderOfMagnitude = exp
                else:
                    self.orderOfMagnitude = 0
        # Compute offset if values are tightly clustered.
        if self._useOffset:
            vmin, vmax = min(self.locs), max(self.locs)
            dv = vmax - vmin
            absmean = abs((vmin + vmax) * 0.5)
            if dv > 0 and absmean / dv > 1e3:
                # Round midpoint to a "nice" number.
                self.offset = _np.round(
                    (vmin + vmax) * 0.5,
                    -int(_np.floor(_np.log10(dv))) + 1)
            else:
                self.offset = 0.0
        else:
            self.offset = 0.0

    def get_offset(self):
        if self.orderOfMagnitude == 0 and self.offset == 0:
            return ''
        parts = []
        if self.orderOfMagnitude != 0:
            if self._useMathText:
                parts.append(f'$\\times 10^{{{self.orderOfMagnitude}}}$')
            else:
                parts.append(f'1e{self.orderOfMagnitude:+d}')
        if self.offset != 0:
            parts.append(f'{self.offset:+g}')
        return '  '.join(parts)


class LogFormatter(Formatter):
    """Format ticks on a log-scaled axis as ``base^k`` strings."""

    def __init__(self, base=10.0, labelOnlyBase=False, minor_thresholds=(1, 0.4),
                 linthresh=None):
        self._base = float(base)
        self.labelOnlyBase = bool(labelOnlyBase)
        self.minor_thresholds = minor_thresholds
        self.linthresh = linthresh

    @property
    def base_value(self):
        return self._base

    def __call__(self, x, pos=None):
        if x <= 0:
            return ''
        b = self._base
        # Detect whether x is an exact power of base.
        with _np.errstate(divide='ignore', invalid='ignore'):
            fx = _np.log(x) / _np.log(b)
            is_int = abs(fx - round(fx)) < 1e-9
        if self.labelOnlyBase and not is_int:
            return ''
        if is_int:
            exp = int(round(fx))
            return f'{int(b)}^{exp}' if b == int(b) else f'{b}^{exp}'
        # In-between values: render plain decimal.
        return f'{x:g}'

    def set_base(self, base):
        self._base = float(base)

    def set_label_minor(self, labelOnlyBase):
        # Upstream: passing False here means label all minor too.
        self.labelOnlyBase = not bool(labelOnlyBase)


class LogFormatterExponent(LogFormatter):
    """Show only the exponent: 100 → '2', 1000 → '3'."""

    def __call__(self, x, pos=None):
        if x <= 0:
            return ''
        b = self._base
        fx = _np.log(x) / _np.log(b)
        if abs(fx - round(fx)) < 1e-9:
            return f'{int(round(fx))}'
        if self.labelOnlyBase:
            return ''
        return f'{fx:.2f}'


class LogFormatterMathtext(LogFormatter):
    """Render with LaTeX math: ``$10^{k}$``."""

    def __call__(self, x, pos=None):
        if x <= 0:
            return ''
        b = self._base
        fx = _np.log(x) / _np.log(b)
        if abs(fx - round(fx)) < 1e-9:
            exp = int(round(fx))
            return f'${int(b) if b == int(b) else b}^{{{exp}}}$'
        if self.labelOnlyBase:
            return ''
        return f'${x:g}$'


class LogFormatterSciNotation(LogFormatterMathtext):
    """Like LogFormatterMathtext but always shows full mantissa·base^exp."""

    def __call__(self, x, pos=None):
        if x <= 0:
            return ''
        b = self._base
        # Use log10 directly when base=10 to avoid the
        # log(1000)/log(10) ≈ 2.9999999996 floor-rounding trap.
        raw = (_np.log10(x) if b == 10 else _np.log(x) / _np.log(b))
        nearest = round(raw)
        if abs(raw - nearest) < 1e-9:
            return f'${int(b) if b == int(b) else b}^{{{int(nearest)}}}$'
        exp = int(_np.floor(raw))
        mantissa = x / (b ** exp)
        return f'${mantissa:g}\\times {int(b) if b == int(b) else b}^{{{exp}}}$'


class PercentFormatter(Formatter):
    """Format x as a percentage: x/xmax → 100*x/xmax with ``symbol`` suffix."""

    def __init__(self, xmax=100, decimals=None, symbol='%', is_latex=False):
        self.xmax = float(xmax)
        self.decimals = decimals
        self._symbol = symbol
        self.is_latex = bool(is_latex)

    @property
    def symbol(self):
        return self._symbol

    @symbol.setter
    def symbol(self, s):
        self._symbol = s

    def convert_to_pct(self, x):
        return 100.0 * x / self.xmax

    def format_pct(self, x, display_range):
        """Format ``x`` as a percent string, picking decimals from
        ``display_range`` (the range of values being formatted) when
        the user hasn't pinned ``decimals``."""
        pct = self.convert_to_pct(x)
        if self.decimals is not None:
            d = self.decimals
        else:
            # Choose enough decimals to distinguish neighboring labels.
            if display_range <= 0:
                d = 0
            else:
                d = max(0, -int(_np.floor(_np.log10(display_range))) + 1)
        s = f'{pct:.{d}f}'
        # Escape % in LaTeX mode.
        if self.is_latex:
            return s + r'\%'
        return s + self._symbol

    def __call__(self, x, pos=None):
        # Compute display_range from locs if known, else fall back.
        rng = (max(self.locs) - min(self.locs)) if self.locs else 100.0
        rng = self.convert_to_pct(rng)
        return self.format_pct(x, rng)


class EngFormatter(Formatter):
    """Engineering-notation formatter (with SI prefix)."""

    ENG_PREFIXES = {
        -24: 'y', -21: 'z', -18: 'a', -15: 'f', -12: 'p', -9: 'n', -6: 'μ',
        -3: 'm', 0: '', 3: 'k', 6: 'M', 9: 'G', 12: 'T', 15: 'P', 18: 'E',
        21: 'Z', 24: 'Y',
    }

    def __init__(self, unit='', places=None, sep=' ', usetex=None, useMathText=None):
        self.unit = unit
        self.places = places
        self.sep = sep
        self._usetex = usetex
        self._useMathText = useMathText

    def format_eng(self, num):
        """Render ``num`` in engineering notation with an SI prefix."""
        import math
        num = float(num)
        if num == 0:
            mantissa = 0.0
            pow10 = 0
        else:
            sign = -1 if num < 0 else 1
            absnum = abs(num)
            pow10 = int(math.floor(math.log10(absnum) / 3) * 3)
            pow10 = max(-24, min(24, pow10))
            mantissa = sign * absnum / (10 ** pow10)
        if self.places is None:
            mstr = f'{mantissa:g}'
        else:
            mstr = f'{mantissa:.{self.places}f}'
        prefix = self.ENG_PREFIXES.get(pow10, f'e{pow10}')
        return mstr + (self.sep + prefix if prefix else '')

    def __call__(self, x, pos=None):
        s = self.format_eng(x)
        if self.unit:
            return s + self.unit
        return s

    def get_useMathText(self):
        return self._useMathText

    def set_useMathText(self, v):
        self._useMathText = v

    def get_usetex(self):
        return self._usetex

    def set_usetex(self, v):
        self._usetex = v

    def format_data(self, value):
        return self.format_eng(value) + self.unit

    def format_data_short(self, value):
        return f'{value:g}'


class NullFormatter(Formatter):
    def __call__(self, x, pos=None):
        return ''


class FixedFormatter(Formatter):
    def __init__(self, seq):
        self.seq = list(seq)
        self.offset_string = ''

    def __call__(self, x, pos=None):
        if pos is not None and pos < len(self.seq):
            return self.seq[pos]
        return ''


class DateFormatter(Formatter):
    def __init__(self, fmt, tz=None, *, usetex=None):
        self.fmt = fmt

    def __call__(self, x, pos=None):
        return str(x)


